// AM shipment -> canonical Shipment. Falls back to a realistic sample
// (shape from ApparelMagic's own API docs) if AM has no real shipments yet
// -- nothing's been picked/shipped in the test company so far.
const num = (v) => (v == null || v === '' ? null : Number(v));
const resp = $json.response || [];
const record = resp[0] || {
  id: 'SAMPLE-1000', customer_id: '1', customer_name: 'Best Store Ever',
  date: new Date().toISOString().slice(0,10), tracking_number: '1Z999AA10123456784', bill_of_lading: null,
  qty: '45', qty_boxes: '2', weight: '12.50',
  boxes: [
    { box_number: '1', qty: '25', weight: '6.25', ucc: '00123456700300000229',
      box_items: [ { product_id: '4', attr_2: 'BLK', size: 'M100', style_number: 'JEAN1', description: 'Classic Denim Jean', qty: '25' } ] },
    { box_number: '2', qty: '20', weight: '6.25', ucc: '00123456700300000236',
      box_items: [ { product_id: '4', attr_2: 'BLK', size: 'M100', style_number: 'JEAN1', description: 'Classic Denim Jean', qty: '20' } ] }
  ]
};
const isSample = resp.length === 0;

const shipment = {
  shipmentId: record.id,
  customerId: record.customer_id,
  customerName: record.customer_name ?? null,
  invoiceId: record.invoice_id || null,
  date: record.date ?? null,
  trackingNumber: record.tracking_number || null,
  billOfLading: record.bill_of_lading || null,
  qty: num(record.qty),
  qtyBoxes: num(record.qty_boxes),
  weight: num(record.weight),
  cartons: (record.boxes || []).map((box) => ({
    boxNumber: box.box_number,
    ucc: box.ucc || null,
    qty: num(box.qty),
    weight: num(box.weight),
    items: (box.box_items || []).map((item) => ({
      productId: item.product_id, color: item.attr_2 || null, size: item.size || null,
      styleNumber: item.style_number || null, description: item.description || null,
      qty: num(item.qty), weight: num(item.weight),
    })),
  })),
};
return { json: { shipment, isSample } };

// canonical Shipment -> Orderful 856 message. Schema confirmed live
// against Orderful's API -- see docs/orderful-outbound-schema-notes.md.
const { shipment } = $json;
const shipDate = shipment.date ? new Date(shipment.date) : new Date();
const dateStr = shipDate.toISOString().slice(0, 10).replace(/-/g, '');
const timeStr = shipDate.toISOString().slice(11, 16).replace(':', '');

const hlLoop = [
  {
    hierarchicalLevel: [{ hierarchicalLevelCode: 'S' }],
    N1_loop: [{ partyIdentification: [{ entityIdentifierCode: 'ST', name: shipment.customerName ?? undefined, identificationCodeQualifier: '92', identificationCode: shipment.customerId }] }],
    dateTimeReference: [{ dateTimeQualifier: '011', date: dateStr }],
  },
  { hierarchicalLevel: [{ hierarchicalLevelCode: 'O' }] },
];
for (const carton of shipment.cartons) {
  hlLoop.push({
    hierarchicalLevel: [{ hierarchicalLevelCode: 'P' }],
    ...(carton.ucc ? { marksAndNumbersInformation: [{ marksAndNumbersQualifier: 'GM', marksAndNumbers: carton.ucc }] } : {}),
  });
  for (const item of carton.items) {
    hlLoop.push({
      hierarchicalLevel: [{ hierarchicalLevelCode: 'I' }],
      itemIdentification: [{ productServiceIDQualifier: 'VN', productServiceID: String(item.productId) }],
      itemDetailShipment: [{ numberOfUnitsShipped: String(item.qty), unitOrBasisForMeasurementCode: 'EA' }],
    });
  }
}

const message = {
  transactionSets: [{
    transactionSetHeader: [{ transactionSetIdentifierCode: '856', transactionSetControlNumber: '0001' }],
    beginningSegmentForShipNotice: [{ transactionSetPurposeCode: '00', shipmentIdentification: String(shipment.shipmentId), date: dateStr, time: timeStr, hierarchicalStructureCode: '0001' }],
    HL_loop: hlLoop,
  }],
};
return { json: { orderfulPayload: { stream: 'TEST', type: { name: '856_SHIP_NOTICE_MANIFEST' }, sender: { isaId: 'ORDFLSCLFOOTW' }, receiver: { isaId: 'ODFLRETAILTEST' }, message } } };

