const resp = $json.response || [];
const record = resp[0] || {
  invoice_id: 'SAMPLE-2000', order_id: null, customer_id: '1', customer_po: 'PO6979505951736416',
  date: new Date().toISOString().slice(0,10), date_due: null, terms_id: null,
