const invoice = {
  invoiceId: record.invoice_id, orderId: record.order_id || null, customerId: record.customer_id,
  poNumber: record.customer_po || null, invoiceDate: record.date ?? null, dueDate: record.date_due || null, termsId: record.terms_id || null,
