  trackingNumber: record.tracking_number || null, shipVia: record.ship_via || null,
  totals: { subtotal: num(record.amount_subtotal), discountPct: num(record.pct_discount), discountAmount: num(record.amount_discount), taxRate: num(record.tax_rate), taxAmount: num(record.amount_tax), freightAmount: num(record.amount_freight), total: num(record.amount) },
  lines: (record.invoice_items || []).map((item) => ({ productId: item.product_id, skuId: item.sku_id, color: item.attr_2 || null, size: item.size || null, styleNumber: item.style_number || null, description: item.description || null, qty: num(item.qty), unitPrice: num(item.unit_price), amount: num(item.amount), isTaxable: item.is_taxable === '1' })),
};
return { json: { invoice, isSample } };

// canonical Invoice -> Orderful 810 message. Schema confirmed live
// against Orderful's API -- see docs/orderful-outbound-schema-notes.md.
const { invoice } = $json;
const dateStr = (invoice.invoiceDate || '').replace(/\D/g, '').slice(0, 8) || null;

const message = {
  transactionSets: [{
    transactionSetHeader: [{ transactionSetIdentifierCode: '810', transactionSetControlNumber: '0001' }],
    beginningSegmentForInvoice: [{ transactionSetPurposeCode: '00', invoiceNumber: String(invoice.invoiceId), date: dateStr }],
    N1_loop: [
      { partyIdentification: [{ entityIdentifierCode: 'ST', name: invoice.shipTo.name ?? undefined, identificationCodeQualifier: '92', identificationCode: invoice.customerId }] },
      { partyIdentification: [{ entityIdentifierCode: 'BT', identificationCodeQualifier: '92', identificationCode: invoice.customerId }] },
    ],
    IT1_loop: invoice.lines.map((line, i) => ({
      baselineItemDataInvoice: [{ assignedIdentification: String(i + 1), quantityInvoiced: String(line.qty), unitOrBasisForMeasurementCode: 'EA', unitPrice: String(line.unitPrice), productServiceIDQualifier: 'SK', productServiceID: String(line.skuId) }],
    })),
    totalMonetaryValueSummary: [{ amount: String(invoice.totals.total) }],
  }],
};
return { json: { orderfulPayload: { stream: 'TEST', type: { name: '810_INVOICE' }, sender: { isaId: 'ORDFLSCLFOOTW' }, receiver: { isaId: 'ODFLRETAILTEST' }, message } } };
